"""Generate fixtures with Python's `math.log1p` on the shared inputs in `../../inputs/`.

Where `math.log1p` raises (a `ValueError` at and below -1), the runner writes
`null` for `expected`, and records the exception's name in a parallel `errors`
array.

NaN and the infinities are read and written as the objects which
`@stdlib/number/float64/to-json` writes and `@stdlib/number/float64/reviver`
reads, e.g. `{"type":"float64","value":"+Infinity"}`. Any other object or
string in the inputs is an error, as are the bare `NaN`, `Infinity`, and
`-Infinity` tokens which Python's `json` module would otherwise accept.
"""

import os
import sys
import json
import hashlib
import platform
from datetime import datetime, timezone
import math

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)

# Shared inputs:
INPUTS = os.path.join(DIR, "..", "..", "inputs")

# Non-finite doubles, by the `value` of their JSON representation:
FLOAT64 = {
    "NaN": float("nan"),
    "+Infinity": float("inf"),
    "-Infinity": float("-inf"),
}

# JSON representations of non-finite doubles, as written by `@stdlib/number/float64/to-json`:
JSON_NAN = '{"type":"float64","value":"NaN"}'
JSON_PINF = '{"type":"float64","value":"+Infinity"}'
JSON_NINF = '{"type":"float64","value":"-Infinity"}'


def reject_constant(name):
    """Reject a bare `NaN`, `Infinity`, or `-Infinity` token, which is not JSON."""
    raise ValueError("unexpected token in inputs: " + name)


def decode(v):
    """Decode a JSON value from a shared input file as a double."""
    if isinstance(v, dict):
        if (
            sorted(v.keys()) == ["type", "value"]
            and v["type"] == "float64"
            and isinstance(v["value"], str)
            and v["value"] in FLOAT64
        ):
            return FLOAT64[v["value"]]
        raise ValueError("unexpected object in inputs: " + json.dumps(v))
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        raise ValueError("unexpected value in inputs: " + repr(v))
    return float(v)


def encode(x):
    """Encode a double as a JSON value, matching the shared input files."""
    if x is None:
        return "null"
    if math.isnan(x):
        return JSON_NAN
    if x == float("inf"):
        return JSON_PINF
    if x == float("-inf"):
        return JSON_NINF
    return repr(x)  # shortest round-trip decimal


def libc():
    """Return the C library's name and version."""
    name, version = platform.libc_ver()
    if name:
        return name + " " + version
    return None


def evaluate(x):
    """Evaluate `log1p` over a list of doubles, recording any exception's name."""
    y = []
    errors = []
    for v in x:
        try:
            y.append(math.log1p(v))
            errors.append(None)
        except (ValueError, OverflowError) as err:
            y.append(None)
            errors.append(type(err).__name__)
    return y, errors


def gen(name):
    """Read the shared input file `name`, and write fixtures to a file of the same name.

    # Arguments

    * `name::str`: input and output filename
    """
    with open(os.path.join(INPUTS, name), "rb") as infile:
        raw = infile.read()
    data = json.loads(raw.decode("utf-8"), parse_constant=reject_constant)
    x = [decode(v) for v in data["x"]]
    y, errors = evaluate(x)

    meta = {
        "source": "python::math",
        "function": "math.log1p",
        "implementation": "the C library's log1p, after CPython's own domain checks",
        "versions": {
            "python": platform.python_version()
        },
        "platform": {
            "os": sys.platform,
            "arch": platform.machine(),
            "compiler": None,
            "libc": libc()
        },
        "generated": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "inputs": hashlib.sha256(raw).hexdigest(),
        "regime": data["regime"]
    }

    out = '{"x":[' + ",".join(encode(v) for v in x) + "]"
    out += ',"expected":[' + ",".join(encode(v) for v in y) + "]"
    if any(e is not None for e in errors):
        out += ',"errors":' + json.dumps(errors, separators=(",", ":"))
    out += ',"meta":' + json.dumps(meta, separators=(",", ":")) + "}\n"

    # Write the data to the output filepath as JSON:
    with open(os.path.join(DIR, name), "w", encoding="utf-8") as outfile:
        outfile.write(out)


def main():
    """Generate fixture data."""
    for name in sorted(os.listdir(INPUTS)):
        if name.endswith(".json"):
            gen(name)


if __name__ == "__main__":
    main()
